import { Suspense } from 'react'
import { notFound } from 'next/navigation'
import { getProduct, getProductSlugs, getRelatedProducts } from '@/lib/products'

type Params = Promise<{ slug: string }>
type SearchParams = Promise<{ currency?: string | string[] }>

export function generateStaticParams() {
  return getProductSlugs().map((slug) => ({ slug }))
}

export default function ProductPage({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  return (
    <main>
      <p>Signal Shop collection</p>
      <Suspense fallback={<ProductSkeleton />}>
        <ProductDetails params={params} searchParams={searchParams} />
      </Suspense>
    </main>
  )
}

async function ProductDetails({
  params,
  searchParams,
}: {
  params: Params
  searchParams: SearchParams
}) {
  const { slug } = await params
  const { currency: rawCurrency } = await searchParams
  const currency =
    (Array.isArray(rawCurrency) ? rawCurrency[0] : rawCurrency) ?? 'USD'
  const product = await getProduct(slug, currency)
  if (!product) notFound()

  return (
    <>
      <h1>{product.name}</h1>
      <p>{product.price}</p>
      <section>
        <h2>Related products</h2>
        <Suspense fallback={<p>Loading related products…</p>}>
          <RelatedProducts slug={slug} />
        </Suspense>
      </section>
    </>
  )
}

async function RelatedProducts({ slug }: { slug: string }) {
  const related = await getRelatedProducts(slug)
  return related.map((item) => <p key={item.slug}>{item.name}</p>)
}

function ProductSkeleton() {
  return (
    <>
      <h1>Loading product…</h1>
      <p>Loading price…</p>
    </>
  )
}

